//! The hard-sphere contact radial distribution function of the PC-SAFT model
//! against the exact-source library.
//! Generated by tools/rust_port/validate_pcsaft_rdf.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::rdf::pcsaft_rdf;

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-12;

#[test]
fn the_radial_function_matches_the_source() {
    let mut rows = include_str!("fixtures/pcsaft_rdf.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(header, "case;g;g_t;g_v;g_n;g_tt;g_tv;g_tn;g_vv;g_vn;g_nn");
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 6, "case {row}");
        let components: Vec<&str> = case[0].split(',').collect();
        let count = components.len();
        // The number of values depends on the number of components: the pair
        // correlation function, its temperature and volume derivatives, the
        // derivatives with respect to the mole numbers and their second
        // derivatives.
        assert_eq!(fields.len(), 7 + 3 * count + count * count, "row {row}");
        let temperature: f64 = case[1].parse().expect("the temperature");
        let volume: f64 = case[2].parse().expect("the volume");
        let moles: Vec<f64> = case[3]
            .split(',')
            .map(|value| value.parse().expect("the number of moles"))
            .collect();
        let first: usize = case[4].parse().expect("the first component of the pair");
        let second: usize = case[5].parse().expect("the second component of the pair");
        let model = thermopack_rs::PcSaft::new(&components).expect("the model of the case");
        let rdf = pcsaft_rdf(&model, temperature, volume, &moles, first, second)
            .expect("the radial function");
        let mut native = vec![rdf.g, rdf.temperature, rdf.volume];
        native.extend(rdf.moles.iter().copied());
        native.push(rdf.temperature_second);
        native.push(rdf.temperature_volume);
        native.extend(rdf.temperature_moles.iter().copied());
        native.push(rdf.volume_second);
        native.extend(rdf.volume_moles.iter().copied());
        native.extend(rdf.moles_second.iter().copied());
        for (position, (source, native)) in fields[1..].iter().zip(native.iter()).enumerate() {
            let source: f64 = source.parse().expect("the source value");
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "entry {position} of the case {row}: source {source} native {native}"
            );
        }
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}

#[test]
fn the_pure_fluid_reduces_to_the_hard_sphere_of_the_pure_fluid() {
    // For a pure fluid the packing fractions satisfy zeta_l = zeta_0 d^l, so
    // the pair correlation function of the model is the one of the original
    // for the self pair of the component.
    let model = thermopack_rs::PcSaft::new(&["CO2"]).expect("the model");
    let rdf = pcsaft_rdf(&model, 300.0, 1.0e-3, &[0.1], 0, 0).expect("the radial function");
    assert!(rdf.g > 1.0);
    assert!(rdf.volume < 0.0);
    assert!(rdf.volume_second > 0.0);
    assert!(rdf.temperature != 0.0);
}

#[test]
fn a_wrong_number_of_moles_is_rejected() {
    let model = thermopack_rs::PcSaft::new(&["CO2", "C1"]).expect("the model");
    assert!(pcsaft_rdf(&model, 300.0, 1.0e-3, &[0.1], 0, 0).is_err());
    assert!(pcsaft_rdf(&model, 300.0, 1.0e-3, &[0.1, 0.1, 0.1], 0, 0).is_err());
    assert!(pcsaft_rdf(&model, 300.0, -1.0e-3, &[0.1, 0.1], 0, 0).is_err());
    assert!(pcsaft_rdf(&model, 300.0, 1.0e-3, &[-0.1, 0.1], 0, 0).is_err());
    assert!(pcsaft_rdf(&model, 300.0, 1.0e-3, &[0.1, 0.1], 0, 2).is_err());
}
